using System;using System.IO;using System.Linq;using System.Reflection;using System.Runtime.Serialization;using System.Collections.Generic;using ElementalHearts;using Verse;using Verse.AI;
class DiscipleCeremonyRegression {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static T Empty<T>(){return (T)FormatterServices.GetUninitializedObject(typeof(T));}
 static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}
 static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string n=new AssemblyName(e.Name).Name;string p=n=="ElementalHearts"?args[1]:n=="0Harmony"?args[2]:Path.Combine(args[0],n+".dll");return File.Exists(p)?Assembly.LoadFrom(p):null;};try{typeof(DiscipleCeremonyRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  Check(!DiscipleProgressRules.Eligible(49,300000)&&!DiscipleProgressRules.Eligible(50,299999)&&DiscipleProgressRules.Eligible(50,300000),"Ascend milestone boundaries");
  for(int t=-10;t<300;t++)foreach(int duration in new[]{180,210}){float p=CeremonyTimeline.Progress(t,duration),e=CeremonyTimeline.Energy(t,duration);Check(p>=0&&p<=1&&e>=0&&e<=1&&!float.IsNaN(e),"Unbounded ceremony curves");Check(CeremonyTimeline.Lift(t)>=0&&CeremonyTimeline.Lift(t)<=.12f,"Unbounded disciple lift");}
  Check(CeremonyTimeline.Lift(0)==0&&CeremonyTimeline.Lift(210)==0&&CeremonyTimeline.Energy(0,180)==0&&CeremonyTimeline.Energy(180,180)==0,"Visuals do not start/end smoothly");
  var ascend=new JobDriver_AscendDisciple{pawn=Empty<Pawn>(),job=new Job(),ticksLeftThisToil=140};var teach=new JobDriver_ElementalTeach{pawn=Empty<Pawn>(),job=new Job(),ticksLeftThisToil=110};Check(ascend.ElapsedAt(900)==70&&teach.ElapsedAt(900)==70,"Legacy/default timing fallback");Set(ascend,"startedAt",700);Set(teach,"startedAt",700);Check(ascend.ElapsedAt(780)==80&&teach.ElapsedAt(780)==80&&ascend.ElapsedAt(600)==0&&ascend.ElapsedAt(5000)==210,"Saved progress bounds");
  var toils=new List<Toil>((IEnumerable<Toil>)typeof(JobDriver_AscendDisciple).GetMethod("MakeNewToils",F).Invoke(ascend,null));Check(toils.Count==2&&toils[0].defaultDuration==210&&toils[0].initAction!=null&&toils[0].tickAction!=null&&toils[1].initAction!=null,"Ascension ceremony toil lifecycle");
  var p1=Empty<Pawn>();p1.jobs=Empty<Pawn_JobTracker>();p1.jobs.curJob=new Job{def=new JobDef{defName=DiscipleAscension.JobName}};Check(DiscipleAscension.Busy(p1)&&ElementalTeachingSession.Busy(p1),"Ascension does not block other skills/teaching");p1.jobs.curJob.def.defName="Goto";Check(!DiscipleAscension.Busy(p1)&&!ElementalTeachingSession.Busy(p1),"Ascension gate survives interruption");
  var fx=new MapComponent_DiscipleCeremony(null);for(int i=0;i<10000;i++)fx.Track(Empty<Pawn>());Check(((Array)Get(fx,"actors")).Length==32&&((Array)Get(fx,"bursts")).Length==32,"Unbounded ceremony pool");var single=new MapComponent_DiscipleCeremony(null);for(int i=0;i<10000;i++)single.Track(p1);Check(((Pawn[])Get(single,"actors")).Count(p=>p!=null)==1,"Duplicate tracked ceremonies");
  Set(ascend,"lastCue",2);Set(ascend,"committed",true);Set(teach,"lastCue",1);Set(teach,"committed",true);var state=new CeremonySaveCase{ascend=ascend,teach=teach};string file=Path.Combine(Path.GetTempPath(),"DiscipleCeremony_"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"CeremonyTest");Scribe_Deep.Look(ref state,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);foreach(string key in new[]{"ascend/EH_discipleAscendStarted","teach/EH_teachStarted"})Check(xml.SelectSingleNode("CeremonyTest/state/"+key).InnerText=="700","Saved ritual start lost");foreach(string key in new[]{"ascend/EH_discipleAscendCommitted","teach/EH_teachCommitted"})Check(xml.SelectSingleNode("CeremonyTest/state/"+key).InnerText=="True","Saved ritual commitment lost");File.Delete(file);
  Console.WriteLine("PASS: milestone boundaries, bounded smooth ceremony/lift curves, legacy and saved elapsed timing, held native toils, interruption gate cleanup, deduplicated fixed effect pools and native saved commitment/timing for both ceremonies.");
 }
}
public class CeremonySaveCase:IExposable {public JobDriver_AscendDisciple ascend;public JobDriver_ElementalTeach teach;public void ExposeData(){Scribe_Deep.Look(ref ascend,"ascend");Scribe_Deep.Look(ref teach,"teach");}}
